import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.D9E58p8B.js";const h=JSON.parse('{"title":"Lire une interface","description":"","frontmatter":{"title":"Lire une interface"},"headers":[],"relativePath":"agent/lire-interface.md","filePath":"agent/lire-interface.md"}'),i={name:"agent/lire-interface.md"};function o(s,e,l,u,c,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="lire-une-interface" tabindex="-1">Lire une interface <a class="header-anchor" href="#lire-une-interface" aria-label="Permalink to &quot;Lire une interface&quot;">​</a></h1><p>Quand une application expose sa structure, l&#39;agent peut lire ses éléments plutôt que d&#39;interpréter une image : c&#39;est plus précis et plus économe.</p><h2 id="ce-que-vous-demandez" tabindex="-1">Ce que vous demandez <a class="header-anchor" href="#ce-que-vous-demandez" aria-label="Permalink to &quot;Ce que vous demandez&quot;">​</a></h2><blockquote><p>« Liste les boutons de la fenêtre au premier plan. »</p><p>« Qu&#39;y a-t-il sous le curseur ? »</p></blockquote><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><ul><li><a href="/Daimon/reference/touche.html#touche-tree"><code>touche_tree</code></a> renvoie l&#39;arbre d&#39;accessibilité de la fenêtre au premier plan : chaque élément avec son rôle, son libellé et sa position. L&#39;arbre est borné en profondeur (4 par défaut) et expurgé des contenus sensibles. L&#39;agent peut filtrer par <code>roles</code> pour ne garder que, par exemple, les boutons.</li><li><a href="/Daimon/reference/touche.html#touche-probe"><code>touche_probe</code></a> renvoie l&#39;élément situé sous un point de l&#39;écran.</li></ul><p>Ces deux outils sont en <strong>lecture seule</strong> et ne sont pas soumis au plafond des Mains.</p><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><p>Une liste d&#39;éléments, avec leurs positions : celles-ci servent ensuite à agir (voir <a href="/Daimon/agent/agir.html">Agir</a>).</p><h2 id="quand-l-arbre-est-vide" tabindex="-1">Quand l&#39;arbre est vide <a class="header-anchor" href="#quand-l-arbre-est-vide" aria-label="Permalink to &quot;Quand l&#39;arbre est vide&quot;">​</a></h2><p>Certaines applications (applications Win32 anciennes, interfaces dessinées sur mesure, Electron) n&#39;exposent rien. L&#39;agent se rabat alors sur <a href="/Daimon/reference/vue.html#vue-find"><code>vue_find</code></a>, qui localise un texte à l&#39;écran par OCR.</p><h2 id="si-l-appel-est-refuse" tabindex="-1">Si l&#39;appel est refusé <a class="header-anchor" href="#si-l-appel-est-refuse" aria-label="Permalink to &quot;Si l&#39;appel est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Ce que l&#39;agent doit faire</th></tr></thead><tbody><tr><td><code>accessibility_permission_denied</code></td><td>L&#39;autorisation <strong>Accessibilité</strong> manque : <a href="/Daimon/guide/autorisations.html">Autorisations</a></td></tr><tr><td><code>excluded</code></td><td>La cible appartient à une application que vous avez protégée : l&#39;agent n&#39;insiste pas</td></tr><tr><td><code>snapshot_failed</code></td><td>La lecture a échoué : réessayer, puis appeler <code>daimon_doctor</code></td></tr></tbody></table><p>Détail complet : <a href="/Daimon/reference/touche.html">Touché</a>.</p>',14)])])}const f=a(i,[["render",o]]);export{h as __pageData,f as default};
